 "content": "def transform(grid):
    """Repeat the non-divider tile across the rectangular lattice of panels."""
    h, w = len(grid), len(grid[0])
    # Divider rows/columns are full lines of a color distinct from the panel background.
    row_divs = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != grid[0][0]]
    col_divs = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h)) and grid[0][c] != grid[0][0]]
    # The examples use uniformly colored separator lines; locate their row/column indices.
    row_bounds = [-1] + row_divs + [h]
    col_bounds = [-1] + col_divs + [w]
    row_panels = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_panels = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]
    # Use the occupied panel (one containing non-background colors) as the motif.
    bg = grid[0][0]
    chosen = None
    for r0, r1 in row_panels:
        for c0, c1 in col_panels:
            if any(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1)):
                chosen = (r0, r1, c0, c1)
                break
        if chosen:
            break
    if chosen is None:
        return [row[:] for row in grid]
